    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var data = eval("scwin.data" + selectbox1.getValue());
    dataList1.setData(data.slice(0));
}
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_groupbyFilterBoxFormatter = function(data) {
    console.log(data);
    var label = "";
    var labelArr = [];
    for (var i = 0; i < data.length; i++) {
        var s_label = "";
        var obj = data[i];
        var header = obj.header;
        var filter = obj.filter;
        debugger;
        for (var j = 0; j < filter.length; j++) {
            if (filter[j].gate)
                s_label = s_label + " " + filter[j].gate + " ";
            var values = filter[j].values;
            if (values.join)
                values = "[" + values.join(" ,") + "]";
            s_label = s_label + filter[j].operator + " " + values;
        }
        s_label = "(" + header + " " + s_label + ")";
        labelArr.push(s_label);
    }
    label = labelArr.join(" & ");
    console.log('label:' + label);
    return label;
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 분류항목의 filter(역삼각형)를 클릭하여 'sam/ple1'로 필터링을 하고 하단의 groupbyFilterBox의 표현값을 확인한다.
    //1. After running the sample, click filter (inverted triangle) of the classification item to filter by 'sam / ple1' and check the expression value of the groupbyFilterBox at the bottom.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_column21_filter').click()");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_customFilter_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_customFilter_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_column21_filter').click()");
    //Verify step 1. 하단의 groupbyFilterBox에 데이터가 '((분류2=sam/ple1))'형식으로 표시된다.이전에는 ((분류2 = sam OR 분류2 = /ple1)) 로 표시됨
    //1. In the groupbyFilterBox at the bottom, the data is displayed in the format '((classification 2 = sam / ple1)).' Previously, ((classification 2 = sam OR classification 2 = / ple1))
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_groupbyFilterBox_select_label').innerText == '((분류2 = sam/ple1))'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
